[{"order":1,"type":"heading","text":"ScriptableObjects Architecture & State Management in Unity"},{"order":2,"type":"paragraph","text":"Managing game state effectively in Unity can become complex when relying solely on Monobehaviours attached to scene objects. ScriptableObjects offer an architectural pattern that decouples data from logic, enabling robust state management, easy saving/loading, and cross-scene communication."},{"order":3,"type":"subheading","text":"Why Use ScriptableObjects for State?"},{"order":4,"type":"bullet_point","text":"Independent of Scene Lifecycle: ScriptableObjects live in project assets, meaning their values persist across scene loads."},{"order":5,"type":"bullet_point","text":"Memory Efficiency: Multiple instances in a scene can reference the exact same data asset without duplicating memory."},{"order":6,"type":"bullet_point","text":"Designer Friendly: Designers can tweak values directly in the Inspector during play mode, and those values can persist if configured properly."},{"order":7,"type":"subheading","text":"Step 1: Creating a Variable ScriptableObject"},{"order":8,"type":"paragraph","text":"First, create a wrapper for primitive types like integers or floats. This allows other components to observe value changes."},{"order":9,"type":"code","text":"using UnityEngine;

[CreateAssetMenu(fileName = "IntVariable", menuName = "ScriptableObjects/Variables/IntVariable")]
public class IntVariable : ScriptableObject
{
    public int Value;
}"},{"order":10,"type":"subheading","text":"Step 2: Implementing a Runtime Game State"},{"order":11,"type":"paragraph","text":"Next, build a GameState asset that aggregates your variables. This centralized hub holds all critical metrics for your game session."},{"order":12,"type":"code","text":"using UnityEngine;

[CreateAssetMenu(fileName = "GameState", menuName = "ScriptableObjects/GameState")]
public class GameState : ScriptableObject
{
    public IntVariable PlayerHealth;
    public IntVariable PlayerScore;

    public void ResetState()
    {
        PlayerHealth.Value = 100;
        PlayerScore.Value = 0;
    }
}"},{"order":13,"type":"subheading","text":"Step 3: Connecting State to Monobehaviours"},{"order":14,"type":"paragraph","text":"Now, consume the ScriptableObject state inside standard game components like the PlayerController or UI Manager."},{"order":15,"type":"code","text":"using UnityEngine;
using UnityEngine.UI;

public class PlayerUI : MonoBehaviour
{
    public IntVariable PlayerHealth;
    public Text HealthText;

    void Update()
    {
        HealthText.text = "Health: " + PlayerHealth.Value;
    }
}"},{"order":16,"type":"subheading","text":"Important Pitfall: Play Mode Persistence"},{"order":17,"type":"paragraph","text":"Because ScriptableObjects exist as project assets, any modifications made during Play Mode persist after you exit Play Mode by default. To prevent data pollution, always reset your variables on application start or implement an initialization method in your main bootstrap scene."}]
